 static int count;static readonly BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);count++;Console.WriteLine("PASS: "+name);}
 static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,Flags).GetValue(o);}
 static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,Flags).Invoke(o,args);}
 static void Pump(int ms){var watch=Stopwatch.StartNew();while(watch.ElapsedMilliseconds<ms){Application.DoEvents();Thread.Sleep(5);}}
 static void Idle(MainForm main){var watch=Stopwatch.StartNew();while(Field<bool>(main,"busy")){Pump(20);if(watch.ElapsedMilliseconds>12000)throw new TimeoutException("UI did not settle");}Pump(50);}
 static Control Find(Control c,string text){if(c.Text==text)return c;foreach(Control child in c.Controls){var found=Find(child,text);if(found!=null)return found;}return null;}
 static int Port(){var l=new TcpListener(IPAddress.Loopback,0);l.Start();int p=((IPEndPoint)l.LocalEndpoint).Port;l.Stop();return p;}
 static bool Key(MainForm main,Keys keys){object[] args={Message.Create(main.Handle,0,IntPtr.Zero,IntPtr.Zero),keys};return (bool)Call(main,"ProcessCmdKey",args);}
 [STAThread] static int Main(string[] args){string root=Path.Combine(Path.GetTempPath(),"aurora-experience-"+Guid.NewGuid().ToString("N"));MainForm main=null;
  try{Application.EnableVisualStyles();var store=new Store(root);store.State.CorePath=Path.GetFullPath(args[0]);store.State.Port=Port();store.State.ApiPort=Port();main=new MainForm(store,false);main.Show();Call(main,"ToggleConnection");Check(Field<int>(main,"page")==1&&!Field<Engine>(main,"engine").Running,"connect without a profile opens subscription onboarding");Check(!Find(main,"应用选中").Enabled&&!Find(main,"更新全部").Enabled,"empty subscription actions are disabled");
   var yaml=new StringBuilder("proxies:\n");for(int i=0;i<80;i++)yaml.Append("  - name: 节点 "+i.ToString("000")+"\n    type: http\n    server: 127.0.0.1\n    port: 9\n");yaml.Append("proxy-groups:\n  - name: A-FIRST\n    type: select\n    proxies:\n");for(int i=0;i<80;i++)yaml.Append("      - 节点 "+i.ToString("000")+"\n");yaml.Append("rules:\n  - MATCH,DIRECT\n");var primary=new Subscription(){Name="Primary local"};store.State.Profiles.Add(primary);store.State.Active=primary.Id;Store.Atomic(store.ProfilePath(primary),yaml.ToString());for(int i=0;i<60;i++)store.State.Profiles.Add(new Subscription(){Name="Subscription "+i,Url="https://example.test/sub/"+i});store.Save();Call(main,"FillProfiles",(object)null);Check(!Find(main,"更新").Enabled,"local profile cannot request URL updates");
   var profiles=Field<ListView>(main,"subscriptions");profiles.Items[42].Selected=true;profiles.Items[42].Focused=true;profiles.TopItem=profiles.Items[35];Pump(30);var oldTop=profiles.TopItem;var oldRow=profiles.Items[42];Call(main,"FillProfiles",(object)null);Check(Object.ReferenceEquals(profiles.Items[42],oldRow)&&profiles.SelectedItems[0]==oldRow&&profiles.TopItem==oldTop,"subscription refresh preserves row identity, selection and viewport");main.PreviewPage(3);main.PreviewPage(1);Pump(100);profiles=Field<ListView>(main,"subscriptions");Check(((Subscription)profiles.SelectedItems[0].Tag).Id==((Subscription)oldRow.Tag).Id&&((Subscription)profiles.TopItem.Tag).Id==((Subscription)oldTop.Tag).Id,"subscription navigation restores selected row and viewport");
   main.PreviewPage(0);Call(main,"ToggleConnection");Idle(main);var engine=Field<Engine>(main,"engine");Check(engine.Running,"one-click connection starts the core");if(SystemProxy.Windows){Check(engine.Proxy.Owned&&Field<SoftButton>(main,"power").Text=="断开代理","one-click connection also enables real system proxy");Call(main,"ToggleConnection");Idle(main);Check(engine.Running&&!engine.Proxy.Owned,"disconnecting system proxy retains the core for LAN clients");}else Check(Field<Label>(main,"stateLabel").Text=="内核运行中","core-only state does not imply system proxy is enabled");
   Field<ComboBox>(main,"mode").SelectedIndex=1;Idle(main);Check(store.State.Mode=="rule"&&Field<int>(main,"page")==2&&Field<bool>(main,"pendingGlobal"),"unconfigured global mode preserves rule mode and remembers requested action");Check((Field<ComboBox>(main,"groups").SelectedItem as string)=="GLOBAL"&&!Application.OpenForms.Cast<Form>().Any(x=>x.Modal),"global guidance focuses the correct category without a modal popup");
   var nodes=Field<ListView>(main,"nodes");var target=nodes.Items.Cast<ListViewItem>().First(x=>(x.Tag as string)=="节点 040");target.Selected=true;target.Focused=true;((SoftButton)Find(main,"使用选中节点")).PerformClick();Idle(main);Check(store.State.Mode=="global"&&!Field<bool>(main,"pendingGlobal")&&engine.GlobalTarget()=="节点 040","choosing an exit automatically completes the requested global switch");Check(!Find(main,"使用选中节点").Enabled&&nodes.SelectedItems[0]==target,"already selected manual node disables redundant use action and retains selection");
   nodes.Items.Cast<ListViewItem>().First(x=>(x.Tag as string)=="DIRECT").Selected=true;((SoftButton)Find(main,"使用选中节点")).PerformClick();Idle(main);Field<ComboBox>(main,"groups").SelectedItem="A-FIRST";var samePage=Field<ListView>(main,"nodes");main.Hide();Call(main,"ToggleConnection");Idle(main);Check(main.Visible&&(Field<ComboBox>(main,"groups").SelectedItem as string)=="GLOBAL"&&Object.ReferenceEquals(samePage,Field<ListView>(main,"nodes")),"tray connection guidance reveals window and focuses GLOBAL without rebuilding current node page");nodes=Field<ListView>(main,"nodes");nodes.Items.Cast<ListViewItem>().First(x=>(x.Tag as string)=="节点 041").Selected=true;((SoftButton)Find(main,"使用选中节点")).PerformClick();Idle(main);Check(!Field<bool>(main,"pendingGlobal")&&!Field<bool>(main,"pendingConnect")&&engine.GlobalTarget()=="节点 041","guided connection completes the mode stage and clears its pending intent");if(SystemProxy.Windows)Check(engine.Proxy.Owned,"choosing an exit resumes the pending one-click system-proxy connection");else Check(!Field<ActivityIndicator>(main,"activity").Text.Contains("操作已完成")&&nodes.Items.Cast<ListViewItem>().First(x=>(x.Tag as string)=="节点 041").SubItems[3].Text=="使用中","system-proxy failure does not hide the successfully selected node");
   Field<ComboBox>(main,"groups").SelectedItem="A-FIRST";Field<TextBox>(main,"search").Text="节点";nodes=Field<ListView>(main,"nodes");nodes.Items[40].Selected=true;nodes.Items[40].Focused=true;nodes.TopItem=nodes.Items[35];Pump(30);string top=nodes.TopItem.Tag as string;main.PreviewPage(3);main.PreviewPage(2);Idle(main);nodes=Field<ListView>(main,"nodes");Check((Field<ComboBox>(main,"groups").SelectedItem as string)=="A-FIRST"&&Field<TextBox>(main,"search").Text=="节点"&&(nodes.SelectedItems[0].Tag as string)=="节点 040"&&(nodes.TopItem.Tag as string)==top,"node navigation restores category, query, selected node and scroll position");var same=nodes;main.PreviewPage(2);Check(Object.ReferenceEquals(same,Field<ListView>(main,"nodes")),"clicking current navigation entry does not rebuild the page");
   Field<TextBox>(main,"search").Text="节点 040";Check(Key(main,Keys.Escape)&&Field<TextBox>(main,"search").Text==""&&nodes.SelectedItems.Count==1,"Escape clears search while retaining a surviving selected node");main.PreviewPage(3);Check(Key(main,Keys.Control|Keys.F),"Ctrl+F opens node search");Idle(main);Check(Field<TextBox>(main,"search").Focused,"search focus is restored after asynchronous node fetch");
   Call(main,"Error",new IOException("Failed https://example.test/private?token=SECRET"));Check(!Application.OpenForms.Cast<Form>().Any(x=>x.Modal)&&!Field<ActivityIndicator>(main,"activity").Text.Contains("SECRET"),"routine failure is inline and subscription URL is redacted");Call(Field<ActivityIndicator>(main,"activity"),"OnClick",EventArgs.Empty);Check(Field<int>(main,"page")==3,"clicking inline error opens full logs");
   if(SystemProxy.Windows){string clipboard=Clipboard.ContainsText()?Clipboard.GetText():null;try{Clipboard.SetText("https://example.test/subscription");using(var dialog=new SubscriptionDialog(null,true))Check(dialog.UrlValue=="https://example.test/subscription"&&dialog.NameValue=="","new import pre-fills a URL from clipboard without downloading");Clipboard.SetText("unrelated text");using(var dialog=new SubscriptionDialog(null,true))Check(dialog.UrlValue=="","unrelated clipboard text is ignored");}finally{if(clipboard==null)Clipboard.Clear();else Clipboard.SetText(clipboard);}}
   using(var gate=new ManualResetEvent(false)){Call(main,"Run",(Action)delegate{gate.WaitOne(4000);},(Action)null,"正在执行后台操作…");var nav=Field<SoftButton[]>(main,"nav");Check(nav[3].Enabled,"background operation keeps navigation available");nav[3].PerformClick();Check(Field<int>(main,"page")==3&&Field<RichTextBox>(main,"logs").Enabled,"logs remain readable during a background operation");nav[1].PerformClick();Check(Field<int>(main,"page")==1&&!Find(main,"应用选中").Enabled,"browsing during work keeps mutation actions disabled");gate.Set();Idle(main);Check(Find(main,"应用选中").Enabled,"operation completion restores applicable actions on the current page");}
   string file=Path.Combine(root,"dropped.yml");File.WriteAllText(file,yaml.ToString());Call(main,"ImportDroppedFile",file);Idle(main);Check(Field<int>(main,"page")==1&&store.State.Profiles.Any(x=>x.Name=="dropped"),"drag/drop import validates YAML and opens the imported subscription");
   Console.WriteLine("Completed "+count+" interaction checks.");return 0;
  }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{if(main!=null)main.Dispose();if(Directory.Exists(root))Directory.Delete(root,true);}
 }
